import{_ as t,o,c as r,a0 as n}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Test Plan: Automation Render Method Selection","description":"","frontmatter":{},"headers":[],"relativePath":"planning/test_plans/automation_render_selection.md","filePath":"planning/test_plans/automation_render_selection.md"}'),a={name:"planning/test_plans/automation_render_selection.md"};function i(s,e,l,d,c,u){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="test-plan-automation-render-method-selection" tabindex="-1">Test Plan: Automation Render Method Selection <a class="header-anchor" href="#test-plan-automation-render-method-selection" aria-label="Permalink to &quot;Test Plan: Automation Render Method Selection&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This test plan verifies the &quot;Automation Render Method Selection&quot; feature. The user must be able to select between &quot;Local Browser Rendering&quot; and &quot;Cloud Rendering&quot; in the Automation Modal, and the UI must correctly reflect the rendering status.</p><h2 id="playwright-e2e-guardrails-best-practices" tabindex="-1">Playwright E2E Guardrails &amp; Best Practices <a class="header-anchor" href="#playwright-e2e-guardrails-best-practices" aria-label="Permalink to &quot;Playwright E2E Guardrails &amp; Best Practices&quot;">​</a></h2><ul><li><strong>Mock Data Integrity</strong>: When mocking the <code>workflowState</code> document to simulate rendering progress, ensure all relational foreign keys (e.g., <code>scriptId</code>, <code>projectId</code>) are present so the frontend listener receives the data.</li><li><strong>Race Conditions</strong>: When transitioning the rendering state (e.g., from <code>rendering</code> to <code>complete</code>), add a <code>waitForTimeout(1000)</code> buffer before asserting UI changes to let React <code>onSnapshot</code> settle.</li><li><strong>Locator Selection</strong>: If rendering status text is behind an overlay, use <code>.toBeAttached()</code> or <code>waitForFunction(document.body.textContent)</code> instead of <code>.toBeVisible()</code>.</li></ul><h2 id="e2e-scenarios-playwright" tabindex="-1">E2E Scenarios (Playwright) <a class="header-anchor" href="#e2e-scenarios-playwright" aria-label="Permalink to &quot;E2E Scenarios (Playwright)&quot;">​</a></h2><h3 id="_1-render-method-dropdown-is-visible-and-functional" tabindex="-1">1. Render Method Dropdown is Visible and Functional <a class="header-anchor" href="#_1-render-method-dropdown-is-visible-and-functional" aria-label="Permalink to &quot;1. Render Method Dropdown is Visible and Functional&quot;">​</a></h3><ul><li><strong>Action</strong>: Navigate to Studio and open the Automation Modal.</li><li><strong>Expected</strong>: A dropdown or selector for &quot;Render Method&quot; is attached to the DOM.</li><li><strong>Action</strong>: Click the dropdown.</li><li><strong>Expected</strong>: &quot;Local Browser Rendering&quot; and &quot;Cloud Rendering&quot; are available as options.</li></ul><h3 id="_2-local-browser-rendering-flow" tabindex="-1">2. Local Browser Rendering Flow <a class="header-anchor" href="#_2-local-browser-rendering-flow" aria-label="Permalink to &quot;2. Local Browser Rendering Flow&quot;">​</a></h3><ul><li><strong>Action</strong>: Select &quot;Local Browser Rendering&quot; and click the &quot;Automate&quot; or &quot;Start&quot; button (<code>{ force: true }</code> if necessary).</li><li><strong>Expected</strong>: The system initiates the local browser rendering pipeline.</li><li><strong>Expected</strong>: The &quot;Rendering Status&quot; indicator updates to show local rendering progress.</li><li><strong>Expected</strong>: Mock the local rendering completion via Firestore state update and verify the success state is shown after React settles.</li></ul><h3 id="_3-cloud-rendering-flow" tabindex="-1">3. Cloud Rendering Flow <a class="header-anchor" href="#_3-cloud-rendering-flow" aria-label="Permalink to &quot;3. Cloud Rendering Flow&quot;">​</a></h3><ul><li><strong>Action</strong>: Select &quot;Cloud Rendering&quot; and start the automation workflow.</li><li><strong>Expected</strong>: The system initiates the server-side cloud rendering pipeline.</li><li><strong>Expected</strong>: The &quot;Rendering Status&quot; indicator updates to show cloud rendering progress.</li><li><strong>Expected</strong>: Mock the cloud rendering completion via Firestore state update and verify the success state is shown after React settles.</li></ul><h3 id="_4-edge-cases-error-handling" tabindex="-1">4. Edge Cases &amp; Error Handling <a class="header-anchor" href="#_4-edge-cases-error-handling" aria-label="Permalink to &quot;4. Edge Cases &amp; Error Handling&quot;">​</a></h3><ul><li><strong>Action</strong>: Trigger a rendering failure by mocking the <code>workflowState</code> step status to <code>error</code> during Cloud Rendering.</li><li><strong>Expected</strong>: The Rendering Status indicator reflects the error and allows the user to retry (use <code>.toBeAttached()</code> if behind an overlay).</li><li><strong>Action</strong>: Switch between Local and Cloud rendering before confirming.</li><li><strong>Expected</strong>: The selection is properly saved and persists in the modal state.</li></ul>',14)])])}const p=t(a,[["render",i]]);export{h as __pageData,p as default};
